
(function () {
    var MENU = [
        { id: 'pepperoni', name: 'Laziz Special Pepperoni', desc: 'Our signature — crispy pepperoni cups, double mozzarella and a rich tomato base on fresh hand-tossed dough.', price: 649, img: 'data:image/jpeg;base64,', alt: 'Pepperoni pizza with crispy pepperoni cups and melted cheese', type: 'nonveg', tags: ['Bestseller'] },
        { id: 'margherita', name: 'Classic Margherita', desc: 'The timeless one — tangy tomato sauce, fresh mozzarella and basil on a golden, blistered crust.', price: 399, img: 'data:image/jpeg;base64,', alt: 'Classic margherita pizza with fresh basil and mozzarella', type: 'veg', tags: ['Veg', 'Classic'] },
        { id: 'tikka', name: 'Chicken Tikka Pizza', desc: 'Smoky chicken tikka pieces, onion, capsicum and a gentle desi spice kick — a Janakpur favourite.', price: 599, img: 'data:image/jpeg;base64,', alt: 'Chicken tikka pizza with peppers, onion and melted cheese', type: 'nonveg', tags: ['Bestseller', 'Spicy'] },
        { id: 'bbq', name: 'BBQ Chicken Feast', desc: 'Grilled BBQ chicken, red onion and coriander over a smoky barbecue base with loads of cheese.', price: 649, img: 'data:image/jpeg;base64,', alt: 'BBQ chicken pizza with red onion and coriander', type: 'nonveg', tags: ['Loaded'] },
        { id: 'veggie', name: 'Veggie Supreme', desc: 'A rainbow of capsicum, sweet corn, onion, olives and seasonal veggies on our signature sauce.', price: 499, img: 'data:image/jpeg;base64,', alt: 'Vegetable pizza with colourful peppers, corn, olives and broccoli', type: 'veg', tags: ['Veg', 'Loaded'] },
        { id: 'cheese', name: 'Double Cheese Blast', desc: 'For the cheese lovers — a double layer of mozzarella with a cheesy stuffed-style edge. Pure comfort.', price: 549, img: 'data:image/jpeg;base64,', alt: 'Double cheese pizza with golden melted mozzarella', type: 'veg', tags: ['Veg', 'Kids love it'] }
    ];

    var cart = {}; // id/name -> {name, price, qty}

    function fmt(n) { return 'Rs. ' + n.toLocaleString('en-IN'); }

    // ---- Render menu cards ----
    var grid = document.getElementById('menuGrid');
    MENU.forEach(function (item) {
        var card = document.createElement('article');
        card.className = 'card';
        card.setAttribute('data-type', item.type);
        card.setAttribute('data-tags', item.tags.join(',').toLowerCase());
        var tagsHtml = item.tags.map(function (t) { return '<span class="tag' + (t === 'Bestseller' ? ' gold' : '') + '">' + t + '</span>'; }).join('');
        card.innerHTML =
            '<img class="ph" src="' + item.img + '" alt="' + item.alt + '" loading="lazy" />' +
            '<div class="card-body">' +
            '<div class="card-top"><h3>' + item.name + '</h3><span class="vegdot' + (item.type === 'nonveg' ? ' nonveg' : '') + '" title="' + (item.type === 'nonveg' ? 'Non-veg' : 'Veg') + '"></span></div>' +
            '<p class="desc">' + item.desc + '</p>' +
            '<div class="tagrow">' + tagsHtml + '</div>' +
            '<div class="card-foot"><div class="price"><strong>' + fmt(item.price) + '</strong><small>Sample price · Regular</small></div>' +
            '<span class="add-wrap" data-add="' + item.name + '" data-price="' + item.price + '"></span></div>' +
            '</div>';
        grid.appendChild(card);
    });

    // ---- Add / qty controls everywhere ----
    function renderAddWraps() {
        document.querySelectorAll('.add-wrap').forEach(function (wrap) {
            var name = wrap.getAttribute('data-add');
            var price = parseInt(wrap.getAttribute('data-price'), 10);
            var entry = cart[name];
            var label = wrap.getAttribute('data-label') || '+ Add';
            if (entry && entry.qty > 0) {
                wrap.innerHTML = '<span class="qty-ctrl show"><button type="button" data-dec="' + name + '" aria-label="Remove one">−</button><span>' + entry.qty + '</span><button type="button" data-inc="' + name + '" aria-label="Add one">+</button></span>';
            } else {
                wrap.innerHTML = '<button type="button" class="add-btn" data-addbtn="' + name + '" data-price="' + price + '">' + label + '</button>';
            }
        });
        document.querySelectorAll('[data-addbtn]').forEach(function (btn) {
            btn.addEventListener('click', function () {
                var n = btn.getAttribute('data-addbtn'); var p = parseInt(btn.getAttribute('data-price'), 10);
                cart[n] = { name: n, price: p, qty: (cart[n] ? cart[n].qty : 0) + 1 };
                flyToBasket(btn);
                sync();
                highlightBasket();
            });
        });
        document.querySelectorAll('[data-inc]').forEach(function (btn) {
            btn.addEventListener('click', function () { var n = btn.getAttribute('data-inc'); cart[n].qty++; flyToBasket(btn); sync(); highlightBasket(); });
        });
        document.querySelectorAll('[data-dec]').forEach(function (btn) {
            btn.addEventListener('click', function () { var n = btn.getAttribute('data-dec'); cart[n].qty--; if (cart[n].qty <= 0) delete cart[n]; sync(); });
        });
    }

    // ---- Order panel + sticky bar ----
    var linesEl = document.getElementById('orderLines');
    var emptyEl = document.getElementById('emptyOrder');
    var totalRow = document.getElementById('totalRow');
    var totalAmt = document.getElementById('totalAmt');
    var basketCountEl = document.getElementById('basketCount');
    var sbSub = document.getElementById('sbSub');
    var sbTitle = document.getElementById('sbTitle');
    var sbOrderBtn = document.getElementById('sbOrderBtn');
    var headerBasket = document.getElementById('headerBasket');
    var headerBasketLabel = document.getElementById('headerBasketLabel');
    var headerBasketCount = document.getElementById('headerBasketCount');
    var basketAnnouncement = document.getElementById('basketAnnouncement');
    var copyBtn = document.getElementById('copyBtn');
    var whatsappOrderBtn = document.getElementById('whatsappOrderBtn');
    var basketDrawer = document.getElementById('order');
    var basketClose = document.getElementById('basketClose');
    var basketBackdrop = document.getElementById('basketBackdrop');
    var customerName = document.getElementById('custName');
    var customerNote = document.getElementById('custNote');
    var lastBasketTrigger = null;
    var basketAnimationTimer;

    function showAddSprinkles(source) {
        var rect = source.getBoundingClientRect();
        var centerX = rect.left + rect.width / 2;
        var centerY = rect.top + rect.height / 2;
        var sprinkles = ['✨', '🧀', '✦', '🍅', '✨', '✦'];
        var spread = [
            [-28, -18], [-8, -28], [18, -23],
            [29, 0], [12, 23], [-21, 16]
        ];

        sprinkles.forEach(function (symbol, index) {
            var particle = document.createElement('span');
            particle.className = 'basket-sprinkle';
            particle.textContent = symbol;
            particle.setAttribute('aria-hidden', 'true');
            particle.style.left = centerX + 'px';
            particle.style.top = centerY + 'px';
            document.body.appendChild(particle);

            var offset = spread[index];
            var animation = particle.animate([
                { transform: 'translate3d(-50%, -50%, 0) scale(.55) rotate(-12deg)', opacity: 0 },
                { transform: 'translate3d(-50%, -50%, 0) scale(1) rotate(0deg)', opacity: 1, offset: .2 },
                { transform: 'translate3d(calc(-50% + ' + (offset[0] * 1.25) + 'px), calc(-50% + ' + (offset[1] * 1.25) + 'px), 0) scale(.65) rotate(18deg)', opacity: 0 }
            ], {
                duration: 560,
                delay: index * 18,
                easing: 'cubic-bezier(.16, 1, .3, 1)',
                fill: 'forwards'
            });
            animation.onfinish = animation.oncancel = function () { particle.remove(); };
        });
    }

    function flyToBasket(source) {
        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

        var sourceRect = source.getBoundingClientRect();
        var size = 58;
        var flyer = document.createElement('div');
        flyer.className = 'basket-flyer';
        flyer.setAttribute('aria-hidden', 'true');
        var image = source.closest('.card') && source.closest('.card').querySelector('img.ph');
        var imageSrc = image && image.src;

        if (imageSrc) {
            flyer.style.backgroundImage = 'url("' + imageSrc + '")';
        } else {
            flyer.classList.add('basket-flyer-icon');
            flyer.textContent = '🍕';
        }

        var startX = sourceRect.left + sourceRect.width / 2 - size / 2;
        var startY = sourceRect.top + sourceRect.height / 2 - size / 2;
        flyer.style.left = startX + 'px';
        flyer.style.top = startY + 'px';
        document.body.appendChild(flyer);

        showAddSprinkles(source);
        flyer.style.visibility = 'hidden';

        window.setTimeout(function () {
            flyer.style.visibility = 'visible';
            var reveal = flyer.animate([
                { transform: 'translate3d(0, 5px, 0) rotate(-5deg) scale(.72)', opacity: 0 },
                { transform: 'translate3d(0, -2px, 0) rotate(2deg) scale(1.04)', opacity: 1, offset: .48 },
                { transform: 'translate3d(0, 0, 0) rotate(0deg) scale(1)', opacity: 1 }
            ], {
                duration: 440,
                easing: 'cubic-bezier(.2, .75, .25, 1)'
            });

            reveal.onfinish = function () {
                var basketRect = headerBasket.getBoundingClientRect();
                var endX = basketRect.left + basketRect.width / 2 - size / 2 - startX;
                var endY = basketRect.top + basketRect.height / 2 - size / 2 - startY;
                var flightFrames = [];
                var steps = 30;
                var controlX = endX * .5;
                var controlY = Math.min(0, endY) - 105;

                for (var step = 0; step <= steps; step++) {
                    var progress = step / steps;
                    var inverse = 1 - progress;
                    var x = 2 * inverse * progress * controlX + progress * progress * endX;
                    var y = 2 * inverse * progress * controlY + progress * progress * endY;
                    var scale = 1 - progress * .82;
                    var opacity = 1 - progress * .88;
                    flightFrames.push({
                        transform: 'translate3d(' + x + 'px, ' + y + 'px, 0) scale(' + scale + ') rotate(' + (progress * 12) + 'deg)',
                        opacity: opacity
                    });
                }

                var flight = flyer.animate(flightFrames, {
                    duration: 1180,
                    easing: 'cubic-bezier(.42, 0, .2, 1)',
                    fill: 'forwards'
                });
                flight.onfinish = flight.oncancel = function () { flyer.remove(); };
            };
            reveal.oncancel = function () { flyer.remove(); };
        }, 400);
    }

    function highlightBasket() {
        window.clearTimeout(basketAnimationTimer);
        headerBasket.classList.remove('attention');
        void headerBasket.offsetWidth;
        headerBasket.classList.add('attention');
        headerBasketLabel.textContent = 'View basket';
        basketAnnouncement.textContent = cartCount() + (cartCount() === 1 ? ' item added' : ' items in basket') + '. View basket.';
        basketAnimationTimer = window.setTimeout(function () {
            headerBasket.classList.remove('attention');
            headerBasketLabel.textContent = 'Basket';
        }, 1800);
    }

    function openBasket(trigger) {
        lastBasketTrigger = trigger || headerBasket;
        basketDrawer.classList.add('open');
        basketDrawer.setAttribute('aria-hidden', 'false');
        basketDrawer.inert = false;
        document.body.classList.add('basket-is-open');
        basketClose.focus();
    }

    function closeBasket() {
        if (!basketDrawer.classList.contains('open')) return;
        basketDrawer.classList.remove('open');
        basketDrawer.setAttribute('aria-hidden', 'true');
        basketDrawer.inert = true;
        document.body.classList.remove('basket-is-open');
        if (lastBasketTrigger) lastBasketTrigger.focus();
    }

    document.querySelectorAll('a[href="#order"]').forEach(function (link) {
        link.addEventListener('click', function (event) {
            event.preventDefault();
            openBasket(link);
        });
    });
    basketClose.addEventListener('click', closeBasket);
    basketBackdrop.addEventListener('click', closeBasket);
    basketDrawer.querySelectorAll('a[href="#menu"]').forEach(function (link) {
        link.addEventListener('click', closeBasket);
    });
    document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape') closeBasket();
        if (event.key !== 'Tab' || !basketDrawer.classList.contains('open')) return;
        var focusable = basketDrawer.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), textarea:not([disabled])');
        var first = focusable[0];
        var last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus();
        }
    });

    function cartCount() {
        return Object.keys(cart).reduce(function (sum, name) { return sum + cart[name].qty; }, 0);
    }

    linesEl.addEventListener('click', function (event) {
        var button = event.target.closest('button[data-cart-inc], button[data-cart-dec]');
        if (!button) return;
        var name = button.getAttribute('data-cart-inc') || button.getAttribute('data-cart-dec');
        if (!cart[name]) return;
        if (button.hasAttribute('data-cart-inc')) cart[name].qty++;
        else {
            cart[name].qty--;
            if (cart[name].qty <= 0) delete cart[name];
        }
        sync();
        if (button.hasAttribute('data-cart-inc')) highlightBasket();
    });

    function buildOrderMessage(names, total) {
        var lines = names.map(function (name) {
            var item = cart[name];
            return '- ' + item.name + ' x ' + item.qty + ' - ' + fmt(item.price * item.qty);
        });
        var message = 'Hi Laziz Pizza! I would like to place an order:\n\n' + lines.join('\n') +
            '\n\nEstimated total (sample prices): ' + fmt(total);
        var name = customerName.value.trim();
        var note = customerNote.value.trim();
        if (name) message += '\nName: ' + name;
        if (note) message += '\nNote: ' + note;
        message += '\n\nPlease confirm availability and the final price. Thank you!';
        return message;
    }

    function updateWhatsAppLink() {
        var names = Object.keys(cart);
        if (names.length === 0) {
            whatsappOrderBtn.removeAttribute('href');
            return;
        }
        var total = names.reduce(function (sum, name) { return sum + cart[name].price * cart[name].qty; }, 0);
        whatsappOrderBtn.href = 'https://wa.me/9779822382510?text=' + encodeURIComponent(buildOrderMessage(names, total));
    }

    customerName.addEventListener('input', updateWhatsAppLink);
    customerNote.addEventListener('input', updateWhatsAppLink);

    function sync() {
        renderAddWraps();
        var names = Object.keys(cart);
        var total = 0, count = 0;
        linesEl.innerHTML = '';
        names.forEach(function (n) {
            var e = cart[n]; total += e.price * e.qty; count += e.qty;
            var row = document.createElement('div'); row.className = 'order-line';
            row.innerHTML = '<div class="nm"><strong>' + e.name + '</strong><span>' + fmt(e.price) + ' each</span></div>' +
                '<div class="basket-qty" aria-label="Quantity for ' + e.name + '">' +
                '<button type="button" data-cart-dec="' + n + '" aria-label="Remove one ' + e.name + '">−</button>' +
                '<span>' + e.qty + '</span>' +
                '<button type="button" data-cart-inc="' + n + '" aria-label="Add one ' + e.name + '">+</button></div>' +
                '<div class="amt">' + fmt(e.price * e.qty) + '</div>';
            linesEl.appendChild(row);
        });
        basketCountEl.textContent = count + (count === 1 ? ' item' : ' items');
        headerBasketCount.textContent = count;
        headerBasket.setAttribute('aria-label', 'View basket, ' + count + (count === 1 ? ' item' : ' items'));
        headerBasket.classList.toggle('has-items', count > 0);
        copyBtn.disabled = count === 0;
        whatsappOrderBtn.setAttribute('aria-disabled', count === 0 ? 'true' : 'false');
        whatsappOrderBtn.classList.toggle('is-disabled', count === 0);
        updateWhatsAppLink();
        if (names.length === 0) {
            emptyEl.style.display = 'block'; totalRow.style.display = 'none';
            sbTitle.textContent = 'Your basket is empty';
            sbSub.textContent = 'Choose items from the menu to get started';
            sbOrderBtn.textContent = 'Browse menu';
            sbOrderBtn.href = '#menu';
        } else {
            emptyEl.style.display = 'none'; totalRow.style.display = 'flex'; totalAmt.textContent = fmt(total);
            sbTitle.textContent = count + (count === 1 ? ' item' : ' items') + ' in your basket';
            sbSub.textContent = fmt(total) + ' estimated · sample prices';
            sbOrderBtn.textContent = 'Review basket';
            sbOrderBtn.href = '#order';
        }
    }

    // ---- Copy order ----
    copyBtn.addEventListener('click', function () {
        var names = Object.keys(cart);
        if (names.length === 0) return;
        var total = names.reduce(function (sum, n) { return sum + cart[n].price * cart[n].qty; }, 0);
        var txt = buildOrderMessage(names, total);
        function done() { var m = document.getElementById('copiedMsg'); m.classList.add('show'); setTimeout(function () { m.classList.remove('show'); }, 2600); }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(txt).then(done).catch(function () { fallback(); });
        } else { fallback(); }
        function fallback() {
            var ta = document.createElement('textarea'); ta.value = txt; document.body.appendChild(ta); ta.select();
            try { document.execCommand('copy'); } catch (e) { }
            document.body.removeChild(ta); done();
        }
    });

    // ---- Filters ----
    document.querySelectorAll('.chip').forEach(function (chip) {
        chip.addEventListener('click', function () {
            document.querySelectorAll('.chip').forEach(function (c) { c.classList.remove('active'); });
            chip.classList.add('active');
            var f = chip.getAttribute('data-filter');
            document.querySelectorAll('#menuGrid .card').forEach(function (card) {
                var show = true;
                if (f === 'veg') show = card.getAttribute('data-type') === 'veg';
                else if (f === 'nonveg') show = card.getAttribute('data-type') === 'nonveg';
                else if (f === 'bestseller') show = card.getAttribute('data-tags').indexOf('bestseller') !== -1;
                card.style.display = show ? '' : 'none';
            });
        });
    });

    // ---- Mobile nav ----
    var ham = document.getElementById('hamburger');
    var mnav = document.getElementById('mobileNav');
    ham.addEventListener('click', function () {
        var open = mnav.classList.toggle('open');
        ham.setAttribute('aria-expanded', open ? 'true' : 'false');
        ham.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    });
    mnav.querySelectorAll('a').forEach(function (a) {
        a.addEventListener('click', function () { mnav.classList.remove('open'); ham.setAttribute('aria-expanded', 'false'); });
    });

    // ---- Open-now status (Asia/Kathmandu) + today badge ----
    try {
        var now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Kathmandu' }));
        var mins = now.getHours() * 60 + now.getMinutes();
        var isOpen = mins >= 9 * 60 && mins < 21 * 60 + 30;
        var dot = document.getElementById('openDot'); var txt = document.getElementById('openText');
        if (isOpen) { txt.textContent = 'Open now · Closes 9:30 PM today'; }
        else { dot.classList.add('closed'); txt.textContent = 'Closed now · Opens 9:00 AM daily'; }
        var day = now.getDay();
        document.querySelectorAll('.today-badge').forEach(function (b) {
            if (parseInt(b.getAttribute('data-day'), 10) === day) b.style.display = 'inline-block';
        });
    } catch (e) { }

    sync();
})();